    // We do not re‐check those here; we just implement the loop.

    // current coordinates (we use i64 to stay well above n)
    let mut x: i64 = 0;
    let mut y: i64 = 0;
    // last region: Some(true) = A (x>y), Some(false) = B (y>x), None = on the border
